typedef struct {
    unsigned char    opcode;            /* BT_ITEMEFF_* opcode of the source effect class */
    unsigned char    sign;              /* Effect.Sign (0 POSITIVE 1 NEGATIVE 2 NEUTRAL 3 FROM_VALUE 4 FROM_ARG 5 OVERRIDE) */
    unsigned char    storage;           /* Effect.StorageMethod (0 SUM 1 KEY_VALUE 2 REPLACE 3 APPEND_KEY 4 APPEND_KEY_VALUE) */
    unsigned char    strategy;          /* DoubleValueEffect.SumStrategy (0 SUM_BOTH 1 SUM_VALUE_1 2 SUM_VALUE_2) */
    unsigned int     flags;             /* BT_ITFLAG_* bitmask (see flag table) */
    unsigned char    chance_pct;        /* ChanceStatDamageEffect.chance, percent */
    unsigned char    reset_on_hit;      /* TempStatsPerIntervalEffect.reset_on_hit */
    unsigned char    perm_stats_only;   /* GainStatForEveryStatEffect.perm_stats_only */
    unsigned char    scale_missing_hp;  /* ItemExplodingEffect.scale_with_missing_health */
    unsigned char    can_be_grouped;    /* StructureEffect.can_be_grouped */
    unsigned char    is_pet;            /* StructureEffect.is_pet */
    unsigned char    is_structure;      /* PetEffect.is_structure */
    unsigned char    is_burning;        /* TurretEffect.is_burning */
    unsigned char    is_spawning;       /* TurretEffect.is_spawning */
    unsigned char    auto_target;       /* ProjectileEffect.auto_target_enemy */
    unsigned short   key;               /* BT_ISTR_* interned target/source stat key (Effect.key) */
    unsigned short   custom_key;        /* BT_ISTR_* interned Effect.custom_key (effect-storage bucket) */
    unsigned short   text_key;          /* BT_ISTR_* interned Effect.text_key */
    unsigned short   aux_key;           /* BT_ISTR_* key2/stat_scaled/set_cap_to_current_stat/source_id/set_id */
    unsigned short   aux2_key;          /* BT_ISTR_* stat_name/stat_displayed_name (ClassBonusEffect) */
    unsigned short   tracking_key;      /* BT_ISTR_* tracking_key or tracking_text */
    unsigned short   color;             /* BT_ISTR_* outline_color hex (PercentDamageEffect) */
    unsigned short   scene;             /* BT_ISTR_* PackedScene path (pet/structure scene) */
    unsigned short   explosion_scene;   /* BT_ISTR_* PackedScene path (ExplodingEffect) */
    unsigned short   extra_group;       /* BT_ITEM_EXTRA_GROUPS ordinal, per-zone BT_GROUPS row (ExtraEnemyEffect; BT_ITEM_EFF_NONE if none) */
    unsigned short   sub_first;         /* first index into BT_ITEM_EFF_INDEX for effects[]/sub_effects[] */
    unsigned short   sub_count;         /* number of child effects (BT_ITEM_EFF_NONE if none) */
    unsigned short   stats;             /* BT_ITEM_WSTATS row index (or BT_ITEM_EFF_NONE) */
    unsigned short   stats2;            /* secondary BT_ITEM_WSTATS row (Blazemander ranged / landmine) */
    unsigned short   burning;           /* BT_ITEM_BURNING row index (or BT_ITEM_EFF_NONE) */
    unsigned short   child;             /* single nested effect row (explosion_effect / landmine_effect_stat) */
    unsigned short   item;              /* BT_ITEMS index that owns this effect row */
    unsigned short   ca_first;          /* first index into BT_ITEM_CUSTOMARGS */
    unsigned short   ca_count;          /* number of custom args */
    int              value;             /* Effect.value */
    int              value2;            /* DoubleValueEffect/DoubleKeyValueEffect.value2 */
    int              value3;            /* GainStatForKilledEnemiesWhileBurning.value3 */
    int              nb_stat_scaled;    /* GainStatForEveryStatEffect.nb_stat_scaled */
    int              spawn_cooldown;    /* StructureEffect.spawn_cooldown (ticks; -1 = stats.cooldown) */
    int              spawn_in_center;   /* StructureEffect.spawn_in_center (-1 = scene default) */
    int              spawn_around_player; /* StructureEffect.spawn_around_player (-1 = scene default) */
    int              projectile_cooldown; /* ProjectileEffect.cooldown (ticks; -1 = stats.cooldown) */
    int              duration_secs;     /* PercentDamageEffect.duration_secs */
    int              max_stacks;        /* PercentDamageEffect.max_stacks */
    int              max_procs;         /* PercentDamageEffect.max_procs */
    int              hp_threshold;      /* ItemExplodingWhenBelowHPEffect.hp_threshold */
    int              sound_db_mod;      /* ExplodingEffect.sound_db_mod */
    float            interval;          /* TempStatsPerIntervalEffect.interval (seconds) */
    float            boost_zone_scale;  /* DocMothEffect.boost_zone_scale */
    float            double_chance;     /* LootwormEffect.double_chance */
    float            explode_chance;    /* ExplodingEffect.chance (0..1) */
    float            explode_scale;     /* ExplodingEffect.scale */
    float            base_smoke_amount; /* ExplodingEffect.base_smoke_amount */
    float            shooting_animation_speed; /* TurretEffect.shooting_animation_speed */
    float            health_boost;      /* ScapegoatEffect.health_boost */
    float            revive_duration;   /* ScapegoatEffect.revive_duration */
} BtItemEff;

typedef struct { unsigned short stat; float ratio; } BtItemScaling;
