    unsigned short   scaling_first;     /* first index into BT_ITEM_SCALING */
    unsigned short   scaling_count;     /* number of (stat, ratio) scaling rows */
    int              cooldown;          /* WeaponStats.cooldown (ticks) */
    int              damage;            /* WeaponStats.damage */
    int              min_range;         /* WeaponStats.min_range */
    int              max_range;         /* WeaponStats.max_range */
    int              knockback;         /* WeaponStats.knockback */
    int              recoil;            /* WeaponStats.recoil */
    int              sound_db_mod;      /* WeaponStats.sound_db_mod */
    int              additional_cd_every; /* WeaponStats.additional_cooldown_every_x_shots */
    int              speed_percent_modifier; /* WeaponStats.speed_percent_modifier */
    int              nb_projectiles;    /* RangedWeaponStats.nb_projectiles */
    int              piercing;          /* RangedWeaponStats.piercing */
    int              bounce;            /* RangedWeaponStats.bounce */
    int              projectile_speed;  /* RangedWeaponStats.projectile_speed */
