/* Pet behaviour table (brotato_pet_motion.h).  One row per pet class that
 * an item can instantiate, resolved from that pet's scene + *_stats.tres:
 * the MovementBehavior node's script and exported fields, the
 * TargetBehavior script, the Stats speed/health and every interaction
 * Area2D's CircleShape2D (radius + centre, uniform scales composed).
 * zone_*[] is indexed by the BT_PET_Z_* ordinals below; an unused zone is
 * radius 0. */
#define BT_PET_MOVE_FOLLOW_TARGET      0
#define BT_PET_MOVE_FOLLOW_TARGET_STOP 1
#define BT_PET_MOVE_RAND_POS           2
#define BT_PET_MOVE_PATROL             3
#define BT_PET_MOVE_FOLLOW_RAND_POS    4
#define BT_PET_TARGET_NONE   0
#define BT_PET_TARGET_ENEMY  1
#define BT_PET_TARGET_PLAYER 2
#define BT_PET_TARGET_LOOT   3
#define BT_PET_Z_BOOST  0
#define BT_PET_Z_ATTRACT 1
#define BT_PET_Z_PICKUP  2
#define BT_PET_Z_TREE    3
#define BT_PET_Z_HEAL    4
#define BT_PET_Z_TARGET  5
#define BT_PET_Z_PLAYER  6
#define BT_PET_Z_DETECT  7
#define BT_PET_NZONES    8
typedef struct {
    unsigned char  opcode;          /* BT_ITEMEFF_* of the instantiated pet */
    unsigned char  move;            /* BT_PET_MOVE_*                        */
    unsigned char  target;          /* BT_PET_TARGET_*                      */
    unsigned char  stop_close;      /* FollowTarget.stop_close_to_target    */
    unsigned char  is_melee;        /* damages through its own Hitbox       */
    unsigned char  allow_within;    /* FollowRandPos.allow_within           */
    unsigned char  fallback_any;    /* closest_enemy: first enemy when none in range */
    unsigned char  exclude_elite_boss; /* closest_enemy: skip elite/boss    */
    unsigned char  target_player_if_none; /* target disappears -> the player */
    unsigned char  _pad0, _pad1, _pad2;
    unsigned short melee_wstats;    /* WeaponStats row of its own Hitbox (BT_ITEM_EFF_NONE) */
    unsigned short fx_first;        /* first BT_PET_ZONE_FX row             */
    unsigned char  fx_count;        /* BT_PET_ZONE_FX rows                  */
    unsigned char  _pad3;
    float          speed;           /* Stats.speed                          */
    float          speed_rand;      /* Stats.speed_randomization            */
    float          stop_dist;       /* stop distance / range_around_player  */
    float          rand_rand;       /* FollowRandPos.range_randomization    */
    float          patrol_rf;       /* PatrolAroundTheMap.radius_factor     */
    float          edge_x, edge_y;  /* half the pet sprite size (zone inset)*/
    float          health_base;     /* Stats.health                         */
    float          health_per_wave; /* Stats.health_increase_each_wave      */
    float          tree_ratio;      /* Lootworm.tree_damage_ratio (0 = no tree melee) */
    float          zone_r[BT_PET_NZONES];  /* BT_PET_Z_* -> radius           */
    float          zone_x[BT_PET_NZONES];  /*            -> centre offset x  */
    float          zone_y[BT_PET_NZONES];  /*            -> centre offset y  */
    unsigned int   collision_layer; /* pet scene root RigidBody2D.collision_layer */
    unsigned int   collision_mask;  /* pet scene root RigidBody2D.collision_mask  */
} BtPetAI;
/* The pet's own `effects` array, applied to a player inside its zone and
 * unapplied when the player leaves (DocMoth BoostZone; effects/items/
 * double_value_effect.gd + effect.gd). */
#define BT_PET_FX_HP_REGEN_BONUS    0
#define BT_PET_FX_DOUBLE_LIFESTEAL  1
typedef struct {
    unsigned char kind;             /* BT_PET_FX_*                          */
    unsigned char _pad0, _pad1, _pad2;
    float         value;            /* Effect.value                         */
    float         value2;           /* DoubleValueEffect.value2 (hp % threshold) */
} BtPetZoneFx;
