/* Dynamic stat links (GainStatForEveryStatEffect; run_data.gd
 * get_scaling_bonus / gain_stat_for_every_stat_effect): when the item is
 * acquired, gain `value` per `nb` units of the `source` stat into the
 * `target` stat.  Replaces the hand-maintained BtStatLink indices in
 * brotato_state.h, which no longer match this pool's item order. */
typedef struct {
    unsigned short item;        /* BT_ITEMS index owning the link */
    unsigned char  target;      /* core stat id gained (BT_STAT_NONE if outside 0..12) */
    unsigned char  source;      /* core stat id scaled (BT_STAT_NONE if outside 0..12) */
    float          value;       /* gain per `nb` units of source */
    int            nb;          /* nb_stat_scaled (may be -1: treat as 1) */
    unsigned char  perm_stats_only;
    unsigned short target_key;  /* BT_ISTR_* target stat key */
    unsigned short source_key;  /* BT_ISTR_* source stat key */
} BtItemStatLink;
